jQuery(document).ready(function() {

    jQuery("#zccCfForm").submit(function(e){
        e.preventDefault();
    });

    var filteredChannels= [];

    function sortChannelsByType(channelsArray){
        var sortedChannels = [];
        var satelliteChannels = {'type': 'Satellite', 'channels':[]};
        var cableChannels = {'type': 'Cable', 'channels':[]};
        var otaChannels = {'type': 'OTA', 'channels':[]};

        channelsArray.forEach( (channel, index) => {            
            switch(channel.type){
                case 'CABLE':
                    cableChannels.channels.push(channel);
                    break;
                case 'SATELLITE':
                    satelliteChannels.channels.push(channel);
                    break;
                case 'OTA':
                    otaChannels.channels.push(channel);
                    break;         
            }
        });
        sortedChannels.push(cableChannels);
        sortedChannels.push(satelliteChannels);
        sortedChannels.push(otaChannels);

        //clear filtered channels
        filteredChannels= [];

        return sortedChannels;
    }

    function filterChannels(channelList, lineup){                   
        channelList.forEach((channel, index) => {
            if( channel.callSign.includes('NBCSN') || channel.callSign.includes('NBCSN HD')){
                channel['type'] = lineup.type;
                channel['carrier'] = lineup.name;
                filteredChannels.push(channel);
            }                
        });            
    }

    function getChannels(lineups){        
        var channels = [],            
            def = jQuery.Deferred();
            requests = [];

        lineups.forEach( (lineup,index) => {         
             requests.push(jQuery.getJSON( 'https://data.tmsapi.com/v1.1/lineups/'+lineup.lineupId+'/channels', 
                    {
                        api_key :'5d9pqntqzb77a7ga2kfchbaa'
                    }).done( function( data ) {              
                        filterChannels(data, lineup);                                
                    }));
        });

        jQuery.when.apply(jQuery, requests).then(function() { def.resolve(); });

        return def.promise();            
    }

    function getLineups(zip){        
        var def = jQuery.Deferred();
        jQuery('#channel-listing-loading').addClass("loading"); //fire up loading spinner        
        jQuery.getJSON( 'https://data.tmsapi.com/v1.1/lineups', 
                    { 
                        country: 'USA',
                        postalCode :zip,
                        api_key :'5d9pqntqzb77a7ga2kfchbaa'
                    }).done( function( data ) {
                        var requests = [];                    
                        requests.push(getChannels(data));
                        jQuery.when.apply(jQuery, requests).then(function() { def.resolve(); });                                                                                                    
                    });        

        return def.promise();
    }

    jQuery('#zccZip').keypress(function(e) {
        var key = e.which;
        if(key == 13){  // the enter key code
            jQuery('#zccSubmit').click();
            return false;  
        }
    }); 

    jQuery('#zccSubmit').click(function(){

        var zip = (jQuery('#zccZip').val()).replace(/\s* /g,'');

        var isValidZip = /(^\d{5}$)/.test(zip);                
        if(isValidZip){
            jQuery.when(getLineups(zip)).done(function(){            
                var sorted = sortChannelsByType(filteredChannels);
                //hide loading spinner
                jQuery('#channel-listing-loading').removeClass("loading");

                jQuery('#tv-listings-container').remove();
                jQuery('#zcc-bottom').append('<div id="tv-listings-container"><tv-listing-event :types="types" :channels="channels"></tv-listings-event></div>');

                new Vue({
                  el: '#tv-listings-container',
                  data: function () {
                    var data = {};

                    data.types = [];
                    data.channels = [];

                    sorted.forEach( (providerType,index) => {
                        if(providerType.channels.length > 0){
                            data.types.push(providerType.type);
                            providerType.channels.forEach( (channel, index) => {
                                data.channels.push(channel);                            
                            });
                        }
                    });

                    return data;
                  },

                  components: {
                    'tv-listing-event': {
                      template: '<div><template v-for="(type, index) in types"><div class="provider-channels">{{type}} Providers</div><div class="channel-header"><div class="channel-info">Carrier</div><div class="channel-info">Channel Name</div><div class="channel-info">Channel No.</div></div><div class="channel-wrapper" v-for="channel in channels" v-if="channel.type == type.toUpperCase()"><div class="channel-carrier channel-info">{{channel.carrier}}</div><div class="channel-callsign channel-info">{{channel.callSign}}</div><div class="channel-channel channel-info">{{channel.channel}}</div></div></template></div>',                  
                      props: ['types', 'channels']
                    }
                  }
                });
            });
       }
       else{
            jQuery('#tv-listings-container').remove();
            jQuery('#zcc-bottom').append('<div id="tv-listings-container"><span class="error">Please enter a 5 digit U.S. Zip Code</span></div>');
       } 
    });  
});

