      'es': 'Nosotros y nuestros socios utilizamos cookies en este sitio web con fines de mejorar nuestro servicio, obtener data estadística, personalizar la publicidad, medir la efectividad de nuestros anuncios publicitarios, y grabar preferencias del sitio web. Al utilizar este sitio web Ud. da su consentimiento al uso de los cookies. Para más información sobre los cookies, incluyendo cómo manejar su consentimiento visite el enlace sobre nuestras '
    },
    linkText: {
      'en': 'Cookie Policy',
      'es': 'políticas con referencia a los cookies'
    },
    buttonText: {
      'en': 'I AGREE',
      'es': 'CONTINUAR'
    },
    policyLink: {
      'en': 'https://www.nbcuniversal.com/privacy/cookies',
      'es': 'https://www.nbcuniversal.com/privacy-policies/privacy-spanish-european'
    },
    cookieName: 'eu_compliance',
    language: '',
    checkShowPrompt: function (language) {
      ComplianceHelper.setLanguage(language);
      if (!ComplianceHelper.shouldCheckCompliance()) return;
      geoservice().done(function (geo) {
        if (!ComplianceHelper.isUserCountryInEU(geo.country_code)) {
          _cookie_.set(ComplianceHelper.cookieName, '1');
          return;
        } 
        ComplianceHelper.showPrompt();
      });
    },
    setLanguage: function (language) {
      ComplianceHelper.language = (typeof language !== 'undefined') ? language : 'en';
    },
    shouldCheckCompliance: function () {
      return _cookie_.get(ComplianceHelper.cookieName) === false;
    },
    isUserCountryInEU: function (country) {
      return (ComplianceHelper.countriesEU.indexOf(country) !== -1) ? true : false;
    },
    showPrompt: function () {
      var $prompt = $('<div id="sliding-popup" class="sliding-popup-bottom" style="height: auto; width: 100%; bottom: 0px;">')
        .append(
          $('<div/>', {'class': "popup-content"})
          .append(
            $('<div/>', {'id': "popup-text"})
            .append('<p>' + ComplianceHelper.getPromptText() + '</p>')
          )
          .append(ComplianceHelper.getBtn())
        );
      $('body').append($prompt);
    },
    promptButtonHandler: function () {
      _cookie_.set(ComplianceHelper.cookieName, '1');
      $('#sliding-popup.sliding-popup-bottom').remove();
    },
    getBtn: function () {
      return $('<div/>', {'id': "popup-buttons"})
        .append('<button type="button" class="agree-button">' + ComplianceHelper.getTxtByLang('button') + '</button>')
        .on('click', ComplianceHelper.promptButtonHandler);
    },
    getPromptText: function () {
      var url = ComplianceHelper.policyLink[ComplianceHelper.language];
      var link = '<a target="blank" href="' + url + '">' + ComplianceHelper.getTxtByLang('link') + '</a>';
      return ComplianceHelper.getTxtByLang('prompt') + link + '.';
    },
    getTxtByLang: function (type) {
      return ComplianceHelper[type + 'Text'][ComplianceHelper.language];
    }
  };
  ComplianceHelper.checkShowPrompt();
}(jQuery));

#sliding-popup.sliding-popup-bottom {
    background: #d8d8d8;
}
#sliding-popup {
    -ms-flex-line-pack: center;
    align-content: center;
    display: block;
    margin: 0;
    padding: 0;
    right: 0;
    text-align: center;
    width: 100%;
    font-weight: 400;
    z-index: 99999;
}
.sliding-popup-bottom {
    background: url(//nbcsports.com/sites/nbcsports.com/modules/custom/nbcs_eu_cookie_compliance/images/gradient.png) center center scroll repeat-y transparent;
    position: fixed;
}
#sliding-popup .popup-content {
    background-color: transparent;
    display: inline-block;
    margin: 10px auto 0 auto;
    padding: 10px;
    width: 89%;
}
#sliding-popup .popup-content #popup-text {
    color: #fff;
    float: left;
    text-align: left;
    font-size: 1.2em;
    width: 100%;
}
#sliding-popup .popup-content #popup-text p {margin: 0;}
#sliding-popup .popup-content #popup-text h2, #sliding-popup .popup-content #popup-text p {color: #333333;display: block;}
#sliding-popup .popup-content #popup-text a {color:#0000FF; }
#sliding-popup .popup-content #popup-text a:link { color: #0000EE; }
#sliding-popup .popup-content #popup-text a:visited { color: #551A8B; }
#sliding-popup .popup-content #popup-text a:active {color: #FF0000;}
#sliding-popup .popup-content #popup-text a:hover{text-decoration:underline;}
#sliding-popup .popup-content #popup-buttons {
    float: right;
    margin: 20px 0 0 0;
    width: 100%;
    display: inline-block;
}
#sliding-popup .popup-content #popup-buttons button {
    cursor: pointer;
    vertical-align: middle;
    overflow: visible;
    width: auto;
    -webkit-box-shadow: 1px 1px 0 0 grey;
    box-shadow: 1px 1px 0 0 grey;
    background-color: #690;
    border-radius: 6px;
    border: 1px #690 solid;
    display: inline-block;
    color: #fff;
    font-size: 25px;
    padding: 4px 20px;
    text-decoration: none;
}
@media (min-width: 768px) {
#sliding-popup .popup-content {
    background-color: transparent;
    display: inline-block;
    margin: 10px 9%;
    padding: 30px 59px 30px 25px;
    max-width: 80%;
    position: relative;
}
 #sliding-popup .popup-content #popup-text {
    color: #fff;
    float: left;
    text-align: left;
    font-size: 1.2em;
    max-width: 60%;
 }
#sliding-popup .popup-content #popup-buttons {
    float: right;
    margin: 5px 0;
    max-width: 40%;
    display: inline-block;
    position: absolute;
    top: 50%;
    right: 59px;
    -webkit-transform: translateY(-50%);
    transform: translateY(-50%);
}
}



